<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Qiye/lists')}">企业列表</a>|					<a href="javascript:void(0);" class="on">商家列表</a>				</ul>			</div>				<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th>{pigcms{:L_("商家名称")}</th>                                <th>{pigcms{:L_("联系电话")}</th>                                <th>{pigcms{:L_("所在区域")}</th>                                <th class="text-middle">{pigcms{:L_("店铺数量")}</th>						</thead>						<tbody>                        <notempty name="merchants">                            <volist name="merchants" id="s">                                <tr>                                    <td>{pigcms{$s.name}</td>                                    <td>{pigcms{$s.phone}</td>                                    <td>{pigcms{$s.address}</td>                                    <td class="text-middle">{pigcms{$s.store_num}</td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="15">{pigcms{$pagebar}</td></tr>                            <else/>                            <tr><td class="textcenter red" colspan="15">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>				</div><script>  function add_qiye(){      window.o2oTop.artiframe('{pigcms{:U('Qiye/add')}','添加企业',800,500,true,false,false,addbtn,'add',true);  }  function qiye_edit(id){      window.o2oTop.artiframe('{pigcms{:U('Qiye/edit')}'+'&qiye_id='+id,'编辑企业',800,500,true,false,false,addbtn,'add',true);  }</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>